def packing_plans(n,sizes,modulus):
    counts=[1%modulus]+[0]*n
    for units in range(1,n+1):
        total=0
        for size in sizes:
            if size<=units:
                total=combine(total,counts[units-size],modulus)
        counts[units]=total
    return counts[n]
